class Solution { fun stoneGameVII(stones:IntArray):Int{val n=stones.size;val prefix=IntArray(n+1);for(i in stones.indices)prefix[i+1]=prefix[i]+stones[i];val dp=Array(n){IntArray(n)};for(length in 2..n)for(left in 0..n-length){val right=left+length-1;val removeLeft=prefix[right+1]-prefix[left+1]-dp[left+1][right];val removeRight=prefix[right]-prefix[left]-dp[left][right-1];dp[left][right]=maxOf(removeLeft,removeRight)};return dp[0][n-1]} }
